Object.assign(window.STUDY_EXAMS,{"dta301_su26":{"title":"SU26 · FE — 60 câu luyện","short":"SU26 · FE","storageKey":"dta301_unified_su26_60_v2","legacyKey":"dta301_unified_su26_60_v1","notice":"60 câu từ ảnh đề gốc. Mỗi câu có giải thích từng lựa chọn, nguồn và Trick nhớ. Đã sửa 5 key khác tài liệu: câu 6, 15, 38, 53, 60.","questions":[{"id":1,"stem":"Which type of join statement will return all records from the table on the left-hand side (LHS) of the join are considered?","options":["LEFT OUTER JOIN","RIGHT OUTER JOIN","FULL OUTER JOIN","INNER JOIN"],"image":"assets/dta301/su26/01.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":11,"sourceTerm":"LEFT OUTER JOIN","detail":"LEFT OUTER JOIN giữ tất cả các dòng bảng trái, bổ sung dữ liệu khớp bên phải; dòng không khớp có NULL phía phải.","trick":"LEFT giữ hết bên trái.","why":["Đúng bảng được bảo toàn là LHS.","Giữ hết bảng phải, không đảm bảo bảng trái.","Giữ cả hai phía, rộng hơn loại join chỉ rõ giữ LHS mà câu hỏi nhắm tới.","Chỉ giữ dòng có khóa khớp ở cả hai bên."],"caution":"FULL OUTER JOIN cũng chứa tất cả dòng trái nhưng còn giữ mọi dòng phải; A là loại join bảo toàn riêng phía trái theo định nghĩa trong sách.","topic":"SQL và công cụ","gradable":true,"keyChanged":false,"bookPage":332,"pdfPage":352,"reference":"Sách chương 11, trang 332 (PDF trang 352) · Slide chương 11, slide 7, 35","slideNumbers":[7,35],"keywords":["join","all records","left-hand side"]},{"id":2,"stem":"Which of the following represents people providing technical expertise to support analytical projects, such as provisioning and administrating analytical sandboxes, and managing large-scale data architectures that enable widespread analytics within companies and other organizations?","options":["Data Savvy Professionals","Technology and Data Enablers","Deep Analytical Talent","Data Researchers"],"image":"assets/dta301/su26/02.jpg","suppliedKey":"B","multiple":false,"correct":[1],"chapter":1,"sourceTerm":"Technology and Data Enablers","detail":"Nhóm Technology and Data Enablers cung cấp sandbox, quản trị kiến trúc và hạ tầng phục vụ phân tích.","trick":"Enable = tạo điều kiện, dựng hạ tầng.","why":["Thiên về nghiệp vụ và đặt câu hỏi phân tích.","Đúng vai trò hỗ trợ kỹ thuật và kiến trúc dữ liệu.","Tập trung xây và áp dụng mô hình phân tích.","Không phải nhóm vai trò được định nghĩa trong mô hình ba nhóm."],"caution":"","topic":"Big Data và vai trò","gradable":true,"keyChanged":false,"bookPage":20,"pdfPage":40,"reference":"Sách chương 1, trang 20 (PDF trang 40) · Slides chương 1","slideNumbers":[],"keywords":["technical expertise","analytical sandboxes","data architectures"]},{"id":3,"stem":"In decision tree, are the decision or test points","options":["Internal nodes","Splits","Branches","Leaf nodes"],"image":"assets/dta301/su26/03.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":7,"sourceTerm":"internal nodes","detail":"Internal nodes là các điểm kiểm tra/ra quyết định trong cây.","trick":"Node hỏi – branch đi – leaf trả lời.","why":["Đúng nơi kiểm tra một thuộc tính/điều kiện.","Split là thao tác chia tập, không phải tên loại nút.","Branch là nhánh ứng với kết quả phép kiểm tra.","Leaf là nơi đưa ra dự đoán cuối."],"caution":"","topic":"Classification","gradable":true,"keyChanged":false,"bookPage":193,"pdfPage":213,"reference":"Sách chương 7, trang 193 (PDF trang 213) · Slide chương 7, slide 7","slideNumbers":[7],"keywords":["decision tree","decision or test points"]},{"id":4,"stem":"What visual tool is suggested in the text to help choose the optimal number of clusters?","options":["A plot illustrating the WSS for different values of k.","A histogram showing attribute distribution.","A scatter plot of raw attribute values.","A pie chart showing cluster proportions."],"image":"assets/dta301/su26/04.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":4,"sourceTerm":"WSS","detail":"Vẽ WSS theo k và tìm điểm khuỷu giúp chọn k khi mức giảm WSS bắt đầu chậm lại.","trick":"Elbow: thêm cụm mà lợi ít → dừng quanh khuỷu.","why":["Đúng đồ thị WSS theo k.","Histogram cho phân bố thuộc tính, không trực tiếp so tiêu chí theo k.","Scatterplot có thể hỗ trợ quan sát nhưng không phải biểu đồ chọn k đang được mô tả.","Pie chart mô tả tỷ trọng cụm sau phân nhóm, không đánh giá WSS."],"caution":"","topic":"Clustering","gradable":true,"keyChanged":false,"bookPage":123,"pdfPage":143,"reference":"Sách chương 4, trang 123 (PDF trang 143) · Slide chương 4, slide 17, 20, 21","slideNumbers":[17,20,21],"keywords":["visual tool","optimal number of clusters"]},{"id":5,"stem":"Which of the following techniques usually refers to a crude process of stripping affixes based on a set of heuristics with the hope of correctly achieving the goal to reduce inflections or variant forms?","options":["Lemmatization methods","Stemming methods","Classification methods","Clustering methods"],"image":"assets/dta301/su26/05.jpg","suppliedKey":"B","multiple":false,"correct":[1],"chapter":9,"sourceTerm":"stripping affixes","detail":"Stemming cắt tiền tố/hậu tố theo heuristic, không nhất thiết tạo từ đúng từ điển.","trick":"Stem = cắt gốc; Lemma = tra từ điển.","why":["Lemmatization dùng từ điển/ngữ pháp để tìm base form đúng.","Đúng mô tả stripping affixes bằng heuristic.","Classification gán nhãn.","Clustering gom nhóm."],"caution":"","topic":"Text Analysis","gradable":true,"keyChanged":false,"bookPage":258,"pdfPage":278,"reference":"Sách chương 9, trang 258 (PDF trang 278) · Slide chương 9, slide 8","slideNumbers":[8],"keywords":["stripping affixes","heuristics"]},{"id":6,"stem":"In the Project Goals section of presentations for Sponsor and Analyst, we should list top ____ agreed-upon goals.","options":["3–5","5–7","2–3","7–9"],"image":"assets/dta301/su26/06.jpg","suppliedKey":"C","multiple":false,"correct":[0],"chapter":12,"sourceTerm":"Project Goals","detail":"Bảng 12-1 yêu cầu liệt kê top 3–5 mục tiêu đã thống nhất cho cả Sponsor và Analyst.","trick":"Goals: nhớ một bàn tay, 3 đến 5.","why":["Đúng top 3–5 theo bảng 12-1.","Không khớp số mục tiêu trong tài liệu.","Đây là key C có sẵn nhưng không khớp sách/slide.","Quá nhiều so với hướng dẫn 3–5."],"caution":"Key trong ảnh chọn C (2–3); sửa thành A (3–5) theo Table 12-1, sách trang 365.","topic":"Báo cáo và triển khai","gradable":true,"keyChanged":true,"bookPage":365,"pdfPage":385,"reference":"Sách chương 12, trang 365 (PDF trang 385) · Slide chương 12, slide 12, 13","slideNumbers":[12,13],"keywords":["Project Goals","top","agreed-upon goals"]},{"id":7,"stem":"Which of the following can be used to predict the likelihood of an outcome based on the input variables?","options":["Logistic regression","Linear regression","Decision trees","Association rules"],"image":"assets/dta301/su26/07.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":6,"sourceTerm":"likelihood of an outcome","detail":"Trong ngữ cảnh chương Regression, logistic regression mô hình hóa xác suất một kết quả nhị phân theo các biến đầu vào.","trick":"Likelihood/probability + yes/no = logistic.","why":["Lựa chọn trực tiếp nhất cho mô hình xác suất nhị phân trong chương.","Linear regression dùng cho đáp ứng liên tục, không ràng buộc đầu ra trong [0,1].","Cây phân loại cũng có thể trả xác suất theo tỷ lệ ở lá, nên phương án này không bất khả thi về kỹ thuật; A là đáp án dự kiến trong ngữ cảnh regression.","Luật kết hợp mô tả đồng xuất hiện thay vì mô hình xác suất có biến đích như câu hỏi."],"caution":"Câu hỏi rộng: decision trees cũng có thể dự đoán xác suất. A phù hợp nhất theo ngữ cảnh đoạn sách, không nên nhớ rằng chỉ logistic mới làm được.","topic":"Regression","gradable":true,"keyChanged":false,"bookPage":178,"pdfPage":198,"reference":"Sách chương 6, trang 178 (PDF trang 198) · Slide chương 6, slide 31, 34","slideNumbers":[31,34],"keywords":["predict the likelihood","input variables"]},{"id":8,"stem":"What characteristic is highlighted about the Apriori algorithm in the text?","options":["It is one of the earliest and most fundamental algorithms for its purpose.","It is a recently developed, cutting-edge algorithm","It is used for optimizing database structures.","It is designed for real-time data visualization."],"image":"assets/dta301/su26/08.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":5,"sourceTerm":"Apriori","detail":"Apriori là một trong những thuật toán sớm và nền tảng để khai thác frequent itemsets và association rules.","trick":"Apriori = nền tảng market basket.","why":["Đúng mô tả lịch sử/vai trò trong chương.","Sai vì không phải thuật toán mới được phát triển gần đây.","Không phải thuật toán tối ưu cấu trúc CSDL.","Không phải công cụ trực quan hóa realtime."],"caution":"","topic":"Association Rules","gradable":true,"keyChanged":false,"bookPage":137,"pdfPage":157,"reference":"Sách chương 5, trang 137 (PDF trang 157) · Slide chương 5, slide 2, 3, 7","slideNumbers":[2,3,7],"keywords":["characteristic","Apriori algorithm"]},{"id":9,"stem":"In Naive Bayes, the input variables are generally ____, but variations of the algorithm can accept ____ variables.","options":["categorical / continuous","continuous / categorical","continuous / continuous","categorical / categorical"],"image":"assets/dta301/su26/09.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":7,"sourceTerm":"categorical","detail":"Phiên bản Naive Bayes trình bày cơ bản dùng biến categorical; các biến thể như Gaussian NB xử lý biến continuous.","trick":"NB cơ bản phân loại; biến thể nhận liên tục.","why":["Đúng thứ tự categorical trước, continuous sau.","Đảo ngược mô tả của đoạn sách.","Không phản ánh sự mở rộng từ categorical sang continuous.","Không nêu khả năng nhận biến continuous."],"caution":"Đây là cách giới thiệu của tài liệu; trong thực hành có nhiều biến thể NB cho dữ liệu liên tục, nhị phân hoặc đếm.","topic":"Classification","gradable":true,"keyChanged":false,"bookPage":211,"pdfPage":231,"reference":"Sách chương 7, trang 211 (PDF trang 231) · Slide chương 7, slide 55","slideNumbers":[55],"keywords":["Naive Bayes","input variables","variations"]},{"id":10,"stem":"“Focused on two methods: decision trees and naive Bayes” Which of the following classification methods were specifically mentioned in the text?","options":["Decision trees and naive Bayes.","Support vector machines and neural networks.","Linear regression and logistic regression.","K-means and hierarchical clustering."],"image":"assets/dta301/su26/10.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":7,"sourceTerm":"decision trees and","detail":"Chương Classification tập trung hai phương pháp decision trees và Naive Bayes.","trick":"Classification trong chương 7: Tree + Bayes.","why":["Đúng hai phương pháp được nêu trong trích đoạn.","Là các bộ phân loại có thật nhưng không phải cặp phương pháp đang được trích.","Đây là các phương pháp chương Regression.","K-means và hierarchical clustering thuộc học không giám sát."],"caution":"","topic":"Classification","gradable":true,"keyChanged":false,"bookPage":192,"pdfPage":212,"reference":"Sách chương 7, trang 192 (PDF trang 212) · Slide chương 7, slide 54, 75","slideNumbers":[54,75],"keywords":["classification methods","decision trees and naive Bayes"]},{"id":11,"stem":"What step in MapReduce applies an operation to a piece of data?","options":["Map","Reduce","Parsing"],"image":"assets/dta301/su26/11.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":10,"sourceTerm":"applies an operation","detail":"Map áp dụng phép xử lý cho từng phần dữ liệu đầu vào.","trick":"Map xử lý từng mảnh, Reduce gom kết quả.","why":["Đúng bước thao tác trên mỗi phần dữ liệu.","Reduce hợp nhất kết quả trung gian theo key.","Parsing là phân tích cú pháp/văn bản, không phải giai đoạn MapReduce đang hỏi."],"caution":"","topic":"MapReduce và Hadoop","gradable":true,"keyChanged":false,"bookPage":298,"pdfPage":318,"reference":"Sách chương 10, trang 298 (PDF trang 318) · Slide chương 10, slide 6","slideNumbers":[6],"keywords":["MapReduce","applies an operation"]},{"id":12,"stem":"“Presented time series analysis using ARIMA models. Different from other statistical techniques in the sense that most statistical analyses assume the observations are independent of each other. Time series analysis implicitly addresses the case in which any particular observation is somewhat dependent on prior observations.” What is a key difference between time series analysis and most other statistical analyses, according to the text?","options":["Time series analysis implicitly addresses the dependence of observations on prior observations","Time series analysis assumes observations are completely independent.","Time series analysis only deals with categorical data.","Time series analysis ignores the order of data points."],"image":"assets/dta301/su26/12.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":8,"sourceTerm":"dependent","detail":"Time series xem xét sự phụ thuộc giữa quan sát hiện tại với các quan sát trước đó và thứ tự thời gian.","trick":"Time = có trước/sau, có phụ thuộc trễ.","why":["Đúng ý trích đoạn: phụ thuộc vào quá khứ.","Trái với đặc điểm time series đang mô tả.","Time series thường có giá trị số; không chỉ dữ liệu categorical.","Bỏ thứ tự sẽ mất cấu trúc thời gian."],"caution":"","topic":"Time Series","gradable":true,"keyChanged":false,"bookPage":236,"pdfPage":256,"reference":"Sách chương 8, trang 236 (PDF trang 256) · Slide chương 8, slide 8, 13, 46","slideNumbers":[8,13,46],"keywords":["time series analysis","independent","dependent on prior observations"]},{"id":13,"stem":"In the Approach section of presentations for Analyst, we should discuss on","options":["High-level methodology","High-level methodology, Relevant details on modeling techniques and technology","Emphasize key messages","Overview of the modeling technique"],"image":"assets/dta301/su26/13.jpg","suppliedKey":"B","multiple":false,"correct":[1],"chapter":12,"sourceTerm":"Relevant details on modeling","detail":"Approach cho Analyst cần cả phương pháp tổng quan và chi tiết liên quan về kỹ thuật mô hình/công nghệ.","trick":"Analyst hỏi thêm “làm thế nào và bằng gì?”.","why":["Chỉ phần tổng quan, phù hợp sponsor nhưng thiếu độ sâu cho analyst.","Đủ hai thành phần theo bảng 12-1.","Đây là Main Findings.","Đây là Model Description."],"caution":"","topic":"Báo cáo và triển khai","gradable":true,"keyChanged":false,"bookPage":365,"pdfPage":385,"reference":"Sách chương 12, trang 365 (PDF trang 385) · Slides chương 12","slideNumbers":[],"keywords":["Approach section","Analyst"]},{"id":14,"stem":"Which of the following is a correct statement to install RODBC package in R?","options":["install.packages(\"RODBC\")","install.packages(RODBC)","package.install(\"RODBC\")","package.install(RODBC)"],"image":"assets/dta301/su26/14.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":3,"sourceTerm":"install.packages","detail":"Cú pháp là install.packages(\"RODBC\"): đúng tên hàm và tên gói là chuỗi ký tự.","trick":"install.packages: packages có s, tên gói có nháy.","why":["Đúng cú pháp R.","RODBC không có nháy sẽ được hiểu là tên đối tượng, có thể lỗi nếu chưa định nghĩa.","Tên hàm bị đảo, không phải hàm cài gói của base R.","Sai tên hàm và thiếu nháy cho tên gói."],"caution":"","topic":"R và thống kê cơ bản","gradable":true,"keyChanged":false,"bookPage":70,"pdfPage":90,"reference":"Sách chương 3, trang 70 (PDF trang 90) · Slide chương 3, slide 18, 20, 64","slideNumbers":[18,20,64],"keywords":["install","RODBC","R"]},{"id":15,"stem":"A part of ____ involves deciding which aspects of particular datasets will be useful to analyze in later steps.","options":["Data conditioning","Performing ETLT","Developing Initial Hypotheses","Data analysis"],"image":"assets/dta301/su26/15.jpg","suppliedKey":"C","multiple":false,"correct":[0],"chapter":2,"sourceTerm":"particular datasets","detail":"Lựa chọn phần dữ liệu giữ lại, biến đổi hay bỏ đi là quyết định trong Data Conditioning.","trick":"Giữ – sửa – bỏ dữ liệu = conditioning.","why":["Đúng phần quyết định dữ liệu nào hữu ích cho phân tích sau.","ETLT nói về luồng extract, transform, load, transform; không phải tên bước của đoạn trích.","Initial Hypotheses là tạo giả thuyết cần kiểm tra ở Discovery.","Data analysis quá chung, không phải bước cụ thể được sách nêu."],"caution":"Key ảnh chọn C (Developing Initial Hypotheses); sửa A (Data Conditioning), sách mục 2.3.4. ","topic":"Data Analytics Lifecycle","gradable":true,"keyChanged":true,"bookPage":40,"pdfPage":60,"reference":"Sách chương 2, trang 40 (PDF trang 60) · Slides chương 2","slideNumbers":[],"keywords":["particular datasets","useful to analyze in later steps"]},{"id":16,"stem":"What is the primary goal of clustering analysis in economics?","options":["To group similar economic indicators.","To predict weather patterns","To design efficient transportation systems.","To engineer new materials."],"image":"assets/dta301/su26/16.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":4,"sourceTerm":"economics","detail":"Trong bối cảnh economics của câu hỏi, clustering gom các chỉ báo/đối tượng kinh tế tương tự thành nhóm.","trick":"Gom giống nhau = clustering, bất kể lĩnh vực.","why":["Đúng ứng dụng gom đối tượng kinh tế tương tự.","Weather là bài toán lĩnh vực khác, không phải mục tiêu economics ở câu này.","Thiết kế giao thông không phải mục tiêu phân cụm kinh tế được hỏi.","Thiết kế vật liệu thuộc miền ứng dụng khác."],"caution":"Clustering còn có thể gom quốc gia, khách hàng hay mẫu kinh tế. Câu hỏi chỉ nêu một ứng dụng, không giới hạn mọi clustering vào indicators.","topic":"Clustering","gradable":true,"keyChanged":false,"bookPage":118,"pdfPage":138,"reference":"Sách chương 4, trang 118 (PDF trang 138) · Slide chương 4, slide 5, 36","slideNumbers":[5,36],"keywords":["primary goal","clustering analysis","economics"]},{"id":17,"stem":"Does Student's t-test assumes that distributions of the two populations have equal but unknown variances?","options":["Yes","No"],"image":"assets/dta301/su26/17.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":3,"sourceTerm":"Student","detail":"Student t-test hai mẫu gộp giả định phương sai bằng nhau nhưng chưa biết.","trick":"Student = Same variance; Welch = phương sai có thể khác.","why":["Đúng cho pooled two-sample Student t-test.","Sai với giả định được hỏi."],"caution":"Không suy rộng giả định bằng phương sai này cho mọi dạng t-test.","topic":"R và thống kê cơ bản","gradable":true,"keyChanged":false,"bookPage":104,"pdfPage":124,"reference":"Sách chương 3, trang 104 (PDF trang 124) · Slide chương 3, slide 2, 73, 74","slideNumbers":[2,73,74],"keywords":["Student's t-test","equal but unknown variances"]},{"id":18,"stem":"‘Through these steps, data science teams can Identify problems and perform rigorous investigation of the datasets needed for in-depth analysis” According to the provided text, what is a primary capability gained by data science teams through the described steps?","options":["Identifying problems and conducting thorough dataset investigations for in-depth analysis.","Ignoring data inconsistencies to expedite analysis.","Focusing solely on superficial data observations without rigorous investigation.","Avoiding dataset analysis altogether by relying on assumptions."],"image":"assets/dta301/su26/18.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":2,"sourceTerm":"rigorous","detail":"Quy trình có hệ thống giúp xác định bài toán và khảo sát dữ liệu đủ sâu trước khi phân tích.","trick":"Đọc trích đoạn: Identify problems + rigorous investigation.","why":["Diễn đạt đúng hai khả năng trong trích đoạn.","Bỏ qua inconsistency làm giảm chất lượng, trái điều tra kỹ lưỡng.","Superficial trái với rigorous/in-depth.","Dựa hoàn toàn giả định trái với việc khảo sát datasets."],"caution":"","topic":"Data Analytics Lifecycle","gradable":true,"keyChanged":false,"bookPage":26,"pdfPage":46,"reference":"Sách chương 2, trang 26 (PDF trang 46) · Slide chương 2, slide 44","slideNumbers":[44],"keywords":["Identify problems","rigorous investigation","primary capability"]},{"id":19,"stem":"What is the foundational concept behind clustering analysis?","options":["Object similarity based on attributes.","Random object distribution.","Object differentiation based on external factors.","Object manipulation to fit a specific pattern."],"image":"assets/dta301/su26/19.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":4,"sourceTerm":"similarity","detail":"Clustering dựa trên mức giống nhau của đối tượng qua các thuộc tính và thước đo khoảng cách/similarity.","trick":"Trong cụm giống nhau; giữa cụm khác nhau.","why":["Đúng nền tảng phân cụm theo attributes.","Phân bố ngẫu nhiên không bảo đảm tương đồng trong cụm.","Yếu tố ngoài chỉ hữu ích khi đã được biểu diễn phù hợp; đây không phải định nghĩa nền tảng.","Không bẻ dữ liệu để ép khớp mẫu mong muốn."],"caution":"","topic":"Clustering","gradable":true,"keyChanged":false,"bookPage":134,"pdfPage":154,"reference":"Sách chương 4, trang 134 (PDF trang 154) · Slide chương 4, slide 32","slideNumbers":[32],"keywords":["foundational concept","clustering analysis"]},{"id":20,"stem":"If a client application wants to access a particular file stored in HDFS, the application contacts and provides the application with the locations of the various blocks for that file","options":["The NameNode daemon","The DataNode daemon","The Secondary NameNode","The Third NameNode"],"image":"assets/dta301/su26/20.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":10,"sourceTerm":"NameNode","detail":"Client hỏi NameNode để biết block của file đang ở các DataNode nào; sau đó đọc dữ liệu từ DataNodes.","trick":"NameNode giữ địa chỉ; DataNode giữ dữ liệu.","why":["Đúng nơi quản lý metadata và vị trí block.","DataNode phục vụ block dữ liệu, không quản lý toàn bộ bản đồ vị trí file.","Secondary NameNode chủ yếu checkpoint metadata, không phải đầu mối hỏi vị trí block.","Không phải daemon HDFS chuẩn trong tài liệu."],"caution":"","topic":"MapReduce và Hadoop","gradable":true,"keyChanged":false,"bookPage":301,"pdfPage":321,"reference":"Sách chương 10, trang 301 (PDF trang 321) · Slide chương 10, slide 11, 12, 13","slideNumbers":[11,12,13],"keywords":["HDFS","contacts","locations","blocks"]},{"id":21,"stem":"Bayes’ theorem gives the relationship between the probabilities of two events and their ____.","options":["conditional probabilities","conditional confidence","conditional interval","Interval confidence","minimum support"],"image":"assets/dta301/su26/21.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":7,"sourceTerm":"Bayes","detail":"Bayes liên hệ P(A|B) với P(B|A), P(A) và P(B).","trick":"Bayes đảo điều kiện A|B ↔ B|A.","why":["Đúng thuật ngữ xác suất có điều kiện.","Không phải thuật ngữ trong định lý Bayes.","Không phải mối quan hệ định lý này mô tả.","Confidence interval thuộc ước lượng khoảng.","Minimum support thuộc association rules."],"caution":"","topic":"Classification","gradable":true,"keyChanged":false,"bookPage":212,"pdfPage":232,"reference":"Sách chương 7, trang 212 (PDF trang 232) · Slide chương 7, slide 38","slideNumbers":[38],"keywords":["Bayes’ theorem","probabilities of two events"]},{"id":22,"stem":"Which is the task of separating words from the body of text?","options":["Tokenization","Parsing","Search and retrieve","Normalization"],"image":"assets/dta301/su26/22.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":9,"sourceTerm":"Tokenization","detail":"Tokenization chia văn bản thành các token như từ hoặc đơn vị ký hiệu.","trick":"Token = từng mảnh từ.","why":["Đúng thao tác tách từ/token.","Parsing rộng hơn, xây cấu trúc biểu diễn cho phân tích.","Search and retrieval tìm tài liệu đã được xử lý/index.","Normalization chuẩn hóa hình thức, không phải tên thao tác tách từ."],"caution":"","topic":"Text Analysis","gradable":true,"keyChanged":false,"bookPage":264,"pdfPage":284,"reference":"Sách chương 9, trang 264 (PDF trang 284) · Slide chương 9, slide 14, 18","slideNumbers":[14,18],"keywords":["separating words","body of text"]},{"id":23,"stem":"Which of the following refers to a periodic fluctuation, but one that is not as fixed as in the case of a seasonality component?","options":["The trend component","The seasonality component","A cyclic component","The random component"],"image":"assets/dta301/su26/23.jpg","suppliedKey":"C","multiple":false,"correct":[2],"chapter":8,"sourceTerm":"cyclic","detail":"Cyclic component là dao động lặp lại nhưng chu kỳ không cố định như seasonality.","trick":"Season có lịch cố định; Cycle co giãn chu kỳ.","why":["Trend là xu hướng dài hạn.","Seasonality có chu kỳ tương đối cố định, trái câu hỏi.","Đúng thành phần dao động với chu kỳ biến thiên.","Random là phần nhiễu khó dự đoán, không phải dao động chu kỳ."],"caution":"Trong ảnh viết “Acyclic component”; hiểu là “A cyclic component” theo thuật ngữ chương, không phải “acyclic = không chu kỳ”.","topic":"Time Series","gradable":true,"keyChanged":false,"bookPage":235,"pdfPage":255,"reference":"Sách chương 8, trang 235 (PDF trang 255) · Slide chương 8, slide 5","slideNumbers":[5],"keywords":["periodic fluctuation","not as fixed","seasonality"]},{"id":24,"stem":"Is it NOT important to involve the data scientist in data conditioning step because many decisions are made in the data conditioning phase that does not affect subsequent analysis?","options":["True","False"],"image":"assets/dta301/su26/24.jpg","suppliedKey":"B","multiple":false,"correct":[1],"chapter":2,"sourceTerm":"important to involve","detail":"Data Scientist cần tham gia conditioning vì lựa chọn giữ/loại/biến đổi dữ liệu ảnh hưởng trực tiếp phân tích về sau.","trick":"Conditioning ảnh hưởng model → Scientist phải tham gia.","why":["Sai cả ý “NOT important” và “does not affect subsequent analysis”.","Đúng: phát biểu phủ nhận vai trò Data Scientist là sai."],"caution":"","topic":"Data Analytics Lifecycle","gradable":true,"keyChanged":false,"bookPage":40,"pdfPage":60,"reference":"Sách chương 2, trang 40 (PDF trang 60) · Slides chương 2","slideNumbers":[],"keywords":["NOT","data conditioning","does not affect"]},{"id":25,"stem":"Which of the followings is the identification of the documents in a corpus that contain search items such as specific words, phrases, topics, or entities like people or organizations?","options":["Parsing","Search and retrieval","Text mining","Discover meaningful insights"],"image":"assets/dta301/su26/25.jpg","suppliedKey":"B","multiple":false,"correct":[1],"chapter":9,"sourceTerm":"Search and retrieval","detail":"Search and retrieval xác định tài liệu trong corpus chứa từ, cụm từ, chủ đề hoặc thực thể cần tìm.","trick":"Tìm tài liệu nào chứa từ = retrieval.","why":["Parsing tạo cấu trúc từ văn bản.","Đúng nhiệm vụ nhận diện tài liệu liên quan.","Text mining khai thác quan hệ/mẫu từ các biểu diễn đã tạo.","Đây là mục tiêu chung, không phải tên bước truy tìm tài liệu."],"caution":"","topic":"Text Analysis","gradable":true,"keyChanged":false,"bookPage":257,"pdfPage":277,"reference":"Sách chương 9, trang 257 (PDF trang 277) · Slide chương 9, slide 6, 48","slideNumbers":[6,48],"keywords":["identification of the documents","search items"]},{"id":26,"stem":"is textual data with erratic data formats that can be formatted with effort, tools, and time (for instance, web clickstream data that may contain inconsistencies in data values and formats)","options":["Structured data","Semi-structured data","Quasi-structured data","Unstructured data"],"image":"assets/dta301/su26/26.jpg","suppliedKey":"C","multiple":false,"correct":[2],"chapter":1,"sourceTerm":"Quasi-structured","detail":"Quasi-structured là text có định dạng thất thường, có thể định cấu trúc bằng thời gian, công cụ và công sức; ví dụ clickstream không nhất quán.","trick":"Quasi = gần có cấu trúc, nhưng lộn xộn.","why":["Structured có schema rõ và nhất quán.","Semi-structured có dấu hiệu cấu trúc như tags/hierarchy, không khớp định nghĩa erratic trong sách.","Đúng định nghĩa và ví dụ clickstream được nêu.","Unstructured không có mô hình tổ chức rõ như văn bản tự do, ảnh/video."],"caution":"","topic":"Big Data và vai trò","gradable":true,"keyChanged":false,"bookPage":6,"pdfPage":26,"reference":"Sách chương 1, trang 6 (PDF trang 26) · Slide chương 1, slide 10","slideNumbers":[10],"keywords":["erratic data formats","formatted with effort"]},{"id":27,"stem":"Is clustering the use of unsupervised techniques for grouping similar objects?","options":["True","False"],"image":"assets/dta301/su26/27.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":4,"sourceTerm":"unsupervised","detail":"Clustering gom các đối tượng tương tự mà không dùng nhãn đích có sẵn.","trick":"Cluster = nhóm giống nhau, chưa cần nhãn.","why":["Đúng định nghĩa unsupervised clustering.","Sai vì clustering là ví dụ điển hình của học không giám sát."],"caution":"","topic":"Clustering","gradable":true,"keyChanged":false,"bookPage":117,"pdfPage":137,"reference":"Sách chương 4, trang 117 (PDF trang 137) · Slide chương 4, slide 2, 4, 27","slideNumbers":[2,4,27],"keywords":["clustering","unsupervised","grouping similar objects"]},{"id":28,"stem":"Which of the following represents the weight of each term in a document, and it is proportional to the number of occurrences of the term in that document?","options":["Information content (IC)","Term frequency (TF)","Inverse Document Frequency (IDF)","Document Frequency (DF)"],"image":"assets/dta301/su26/28.jpg","suppliedKey":"B","multiple":false,"correct":[1],"chapter":9,"sourceTerm":"term frequency","detail":"TF đo số lần một term xuất hiện trong một tài liệu, có thể được chuẩn hóa.","trick":"TF: Tần suất trong 1 File.","why":["IC là độ thông tin/độ quan trọng xét theo corpus và ontology.","Đúng trọng số dựa trên số lần xuất hiện trong tài liệu.","IDF giảm khi từ xuất hiện ở nhiều tài liệu.","DF đếm số tài liệu chứa từ, không đếm số lần trong một tài liệu."],"caution":"","topic":"Text Analysis","gradable":true,"keyChanged":false,"bookPage":265,"pdfPage":285,"reference":"Sách chương 9, trang 265 (PDF trang 285) · Slide chương 9, slide 3, 15, 17","slideNumbers":[3,15,17],"keywords":["weight of each term","number of occurrences"]},{"id":29,"stem":"What is a primary strength of association rules?","options":["Identifying \"interesting\" and potentially non-obvious relationships within large datasets.","Predicting future outcomes with high accuracy.","Directly controlling and manipulating consumer behavior.","Automatically generating financial forecasts."],"image":"assets/dta301/su26/29.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":5,"sourceTerm":"interesting","detail":"Association rules phát hiện các quan hệ đồng xuất hiện có thể hữu ích và khó thấy bằng quan sát thông thường.","trick":"Association = liên hệ, chưa phải nhân quả.","why":["Đúng thế mạnh phát hiện interesting relationships.","Không bảo đảm dự báo tương lai chính xác cao.","Tìm liên hệ không đồng nghĩa điều khiển hành vi hay chứng minh nhân quả.","Không tự động tạo financial forecasts chỉ từ luật kết hợp."],"caution":"","topic":"Association Rules","gradable":true,"keyChanged":false,"bookPage":138,"pdfPage":158,"reference":"Sách chương 5, trang 138 (PDF trang 158) · Slide chương 5, slide 5, 15, 16","slideNumbers":[5,15,16],"keywords":["primary strength","association rules"]},{"id":30,"stem":"Which of the following is a significant source of Big Data?","options":["Social media platforms.","Traditional paper-based archives.","Isolated, non-networked calculators.","Hand-written historical documents."],"image":"assets/dta301/su26/30.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":1,"sourceTerm":"social media","detail":"Social media sinh dữ liệu số với lượng lớn, nhiều định dạng và tốc độ cao.","trick":"Mạng xã hội = nhiều người × nhiều nội dung × liên tục.","why":["Đúng ví dụ nguồn Big Data thường gặp.","Tài liệu giấy cần số hóa; bản thân kho giấy không phải luồng dữ liệu số lớn thường được hỏi.","Máy tính bỏ túi tách rời không tạo nguồn dữ liệu lớn đa dạng.","Tài liệu viết tay có thể thành dữ liệu sau số hóa, nhưng không là lựa chọn tiêu biểu bằng social media."],"caution":"","topic":"Big Data và vai trò","gradable":true,"keyChanged":false,"bookPage":2,"pdfPage":22,"reference":"Sách chương 1, trang 2 (PDF trang 22) · Slide chương 1, slide 4, 8, 21","slideNumbers":[4,8,21],"keywords":["significant source","Big Data"]},{"id":31,"stem":"is used to analyze a time series that is dependent on another time series?","options":["Autoregressive Moving Average with Exogenous inputs (ARMAX)","Spectral analysis","Generalized Autoregressive Conditionally Heteroscedastic (GARCH)","Kalman filtering"],"image":"assets/dta301/su26/31.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":8,"sourceTerm":"ARMAX","detail":"ARMAX bổ sung biến/chuỗi ngoại sinh để giải thích chuỗi mục tiêu.","trick":"X trong ARMAX = eXogenous input.","why":["Đúng mô hình có đầu vào ngoài từ chuỗi khác.","Spectral analysis khảo sát miền tần số.","GARCH tập trung phương sai/volatility.","Kalman filter dùng mô hình trạng thái ẩn, không phải tên mô hình có X được định nghĩa."],"caution":"","topic":"Time Series","gradable":true,"keyChanged":false,"bookPage":253,"pdfPage":273,"reference":"Sách chương 8, trang 253 (PDF trang 273) · Slide chương 8, slide 46","slideNumbers":[46],"keywords":["time series","dependent on another"]},{"id":32,"stem":"Which of the following section in of presentations for Project Sponsor we should discuss on overview of the modeling technique used in data analytics project?","options":["Key Points Supported with Data","Model Details","Model Description","Main Findings"],"image":"assets/dta301/su26/32.jpg","suppliedKey":"C","multiple":false,"correct":[2],"chapter":12,"sourceTerm":"Model Description","detail":"Model Description cung cấp tổng quan kỹ thuật mô hình cho sponsor.","trick":"Description = mô tả tổng quan; Details = đào sâu.","why":["Key Points Supported with Data dùng biểu đồ hỗ trợ luận điểm.","Model Details có thể lược bỏ hoặc chỉ nói mức cao với sponsor.","Đúng phần overview of modeling technique.","Main Findings nhấn mạnh thông điệp/phát hiện chính."],"caution":"","topic":"Báo cáo và triển khai","gradable":true,"keyChanged":false,"bookPage":365,"pdfPage":385,"reference":"Sách chương 12, trang 365 (PDF trang 385) · Slide chương 12, slide 20, 21","slideNumbers":[20,21],"keywords":["Project Sponsor","overview of the modeling technique"]},{"id":33,"stem":"The process of converting continuous variables into categorical ones is called ____.","options":["discretization","specialization","separation","realization"],"image":"assets/dta301/su26/33.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":7,"sourceTerm":"discretization","detail":"Discretization chia miền giá trị liên tục thành các khoảng/nhãn rời rạc.","trick":"Discrete = rời rạc; tuổi số → nhóm tuổi.","why":["Đúng tên phép chuyển continuous sang categorical.","Specialization không phải tên chuyển đổi này.","Separation chỉ là từ chung, không phải thuật ngữ kỹ thuật được hỏi.","Realization không phải phép chia biến liên tục thành nhóm."],"caution":"","topic":"Classification","gradable":true,"keyChanged":false,"bookPage":211,"pdfPage":231,"reference":"Sách chương 7, trang 211 (PDF trang 231) · Slide chương 7, slide 39, 55","slideNumbers":[39,55],"keywords":["continuous variables","categorical"]},{"id":34,"stem":"____ function can be used to order a set of rows based on some attribute.","options":["RANK()","Order()","Sort()","Having()"],"image":"assets/dta301/su26/34.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":11,"sourceTerm":"RANK()","detail":"RANK() OVER (ORDER BY ...) tạo thứ hạng theo thuộc tính. Câu dùng “order” theo nghĩa xếp hạng trong mục Window Functions.","trick":"RANK xếp hạng; ORDER BY sắp thứ tự kết quả.","why":["Đúng window function mà sách nêu trong đoạn này.","SQL dùng mệnh đề ORDER BY, không có Order() như phương án.","Sort() không phải hàm PostgreSQL được hỏi.","HAVING là mệnh đề lọc nhóm, không phải hàm xếp hạng."],"caution":"RANK không tự đảm bảo thứ tự hiển thị của toàn bộ kết quả SQL; muốn sắp kết quả cần ORDER BY ở truy vấn ngoài.","topic":"SQL và công cụ","gradable":true,"keyChanged":false,"bookPage":343,"pdfPage":363,"reference":"Sách chương 11, trang 343 (PDF trang 363) · Slide chương 11, slide 19, 20","slideNumbers":[19,20],"keywords":["order a set of rows","attribute"]},{"id":35,"stem":"In logistic regression, the ____ is the value where the likelihood function is based only on the intercept term (y = β0).","options":["null deviance","residual deviance","empty deviance","different deviance"],"image":"assets/dta301/su26/35.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":6,"sourceTerm":"null deviance","detail":"Null deviance dựa trên mô hình chỉ có intercept.","trick":"Null: chưa thêm predictor nào.","why":["Đúng chỉ tiêu cho intercept-only model.","Residual deviance thuộc mô hình có các biến giải thích đã chọn.","Không phải tên dùng trong output glm của R và tài liệu.","Không phải thuật ngữ chuẩn của output này."],"caution":"","topic":"Regression","gradable":true,"keyChanged":false,"bookPage":183,"pdfPage":203,"reference":"Sách chương 6, trang 183 (PDF trang 203) · Slide chương 6, slide 43","slideNumbers":[43],"keywords":["logistic regression","only on the intercept term"]},{"id":36,"stem":"What step in MapReduce consolidates the intermediate outputs from the other steps and provides the final output?","options":["Map","Reduce","Gain insights","Parsing"],"image":"assets/dta301/su26/36.jpg","suppliedKey":"B","multiple":false,"correct":[1],"chapter":10,"sourceTerm":"Reduce","detail":"Reduce tổng hợp các output trung gian theo key để tạo output cuối.","trick":"Reduce gom kết quả Map.","why":["Map xử lý đầu vào và phát ra key/value trung gian.","Đúng giai đoạn consolidate output.","Gain insights là mục tiêu phân tích, không phải giai đoạn MapReduce.","Parsing là thao tác xử lý cú pháp/văn bản."],"caution":"","topic":"MapReduce và Hadoop","gradable":true,"keyChanged":false,"bookPage":298,"pdfPage":318,"reference":"Sách chương 10, trang 298 (PDF trang 318) · Slide chương 10, slide 6","slideNumbers":[6],"keywords":["MapReduce","consolidates the intermediate outputs"]},{"id":37,"stem":"What type of analysis technique is described in the text for uncovering relationships among items?","options":["Association rules","Regression analysis.","Time series analysis.","Sentiment analysis."],"image":"assets/dta301/su26/37.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":5,"sourceTerm":"relationships","detail":"Association rules khai thác quan hệ giữa các items trong dữ liệu giao dịch.","trick":"Items cùng xuất hiện → association.","why":["Đúng kỹ thuật tìm quan hệ giữa items.","Regression mô hình hóa biến đích từ biến đầu vào.","Time series khai thác cấu trúc theo thời gian.","Sentiment analysis xác định cảm xúc/thái độ văn bản."],"caution":"","topic":"Association Rules","gradable":true,"keyChanged":false,"bookPage":138,"pdfPage":158,"reference":"Sách chương 5, trang 138 (PDF trang 158) · Slide chương 5, slide 5, 34, 36","slideNumbers":[5,34,36],"keywords":["relationships among items"]},{"id":38,"stem":"Which of the following measures the purity of an attribute?","options":["Entropy","Information gain","Impurity rate","purity rate"],"image":"assets/dta301/su26/38.jpg","suppliedKey":"A","multiple":false,"correct":[1],"chapter":7,"sourceTerm":"purity of an attribute","detail":"Sách và slide phân biệt: Entropy đo impurity, Information gain đo mức tăng purity khi chia theo thuộc tính.","trick":"Entropy = hỗn tạp; Gain = được thêm độ thuần.","why":["Entropy đo impurity, không phải đáp án “purity” theo câu định nghĩa.","Đúng chỉ tiêu mà tài liệu gắn với purity.","Tên này nói về impurity và không phải thước đo được nêu.","Không phải tên chỉ tiêu chuẩn trong hai đại lượng đang học."],"caution":"Key ảnh chọn A; sửa B theo sách mục 7.1.2 và slide 14. Entropy thấp có nghĩa nút thuần hơn, nhưng từ khóa định nghĩa của câu vẫn là Information gain.","topic":"Classification","gradable":true,"keyChanged":true,"bookPage":197,"pdfPage":217,"reference":"Sách chương 7, trang 197 (PDF trang 217) · Slide chương 7, slide 14","slideNumbers":[14],"keywords":["purity","attribute"]},{"id":39,"stem":"In association rules, a relationship may be thought of as interesting rule when the algorithm identifies the relationship with a measure of confidence greater than or equal to a predefined threshold. This predefined threshold is called.","options":["minimum confidence","Interval confidence","Confidence","Lift"],"image":"assets/dta301/su26/39.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":5,"sourceTerm":"minimum confidence","detail":"Luật đáp ứng ngưỡng tin cậy khi confidence ≥ minimum confidence.","trick":"Ngưỡng của confidence = min confidence; của frequent = min support.","why":["Đúng tên ngưỡng tối thiểu cho luật.","Confidence interval là ước lượng khoảng, không phải ngưỡng rule mining.","Confidence là giá trị đo, chưa phải tên ngưỡng.","Lift là tỷ số so với độc lập."],"caution":"","topic":"Association Rules","gradable":true,"keyChanged":false,"bookPage":141,"pdfPage":161,"reference":"Sách chương 5, trang 141 (PDF trang 161) · Slide chương 5, slide 15, 28, 29","slideNumbers":[15,28,29],"keywords":["confidence","greater than or equal","predefined threshold"]},{"id":40,"stem":"‘Through these steps, data science teams can Identify problems and perform rigorous investigation of the datasets needed for in-depth analysis” What is the result of following the steps mentioned in the provided text?","options":["The ability to identify problems and deeply investigate datasets.","A decrease in the need for dataset analysis.","The ability to perform a shallow review of data.","The ability to create data without investigation."],"image":"assets/dta301/su26/40.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":2,"sourceTerm":"rigorous","detail":"Kết quả mô tả ngay trong trích đoạn là xác định vấn đề và khảo sát datasets sâu.","trick":"Identify + investigate = xác định + khảo sát.","why":["Đúng cả hai kết quả trong đoạn.","Đoạn nhấn mạnh điều tra dữ liệu, không giảm nhu cầu đó.","Shallow trái với in-depth.","Không nhắc việc tạo dữ liệu thay cho điều tra."],"caution":"","topic":"Data Analytics Lifecycle","gradable":true,"keyChanged":false,"bookPage":26,"pdfPage":46,"reference":"Sách chương 2, trang 26 (PDF trang 46) · Slide chương 2, slide 44","slideNumbers":[44],"keywords":["Identify problems","rigorous investigation","result"]},{"id":41,"stem":"Which of the following will determine and track where the various blocks of a data file are stored?","options":["The NameNode daemon","The DataNode daemon","The Secondary NameNode","The Third NameNode"],"image":"assets/dta301/su26/41.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":10,"sourceTerm":"NameNode","detail":"NameNode theo dõi metadata và mapping từ file/block đến vị trí DataNodes.","trick":"NameNode là bản đồ block.","why":["Đúng daemon quản lý vị trí block.","DataNode lưu và cung cấp block vật lý.","Secondary NameNode checkpoint metadata, không thay NameNode theo dõi vị trí đang hoạt động.","Không phải daemon chuẩn trong HDFS của chương."],"caution":"","topic":"MapReduce và Hadoop","gradable":true,"keyChanged":false,"bookPage":301,"pdfPage":321,"reference":"Sách chương 10, trang 301 (PDF trang 321) · Slide chương 10, slide 11, 12, 13","slideNumbers":[11,12,13],"keywords":["track where","blocks","stored"]},{"id":42,"stem":"Which of the following is an analytical technique used to model the relationship between several input variables and a continuous outcome variable?","options":["Linear regression","K-means","Association rules","Decision trees"],"image":"assets/dta301/su26/42.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":6,"sourceTerm":"continuous outcome","detail":"Linear regression mô hình hóa quan hệ giữa các biến đầu vào và một biến đáp ứng liên tục.","trick":"Outcome là số liên tục → linear regression.","why":["Đúng định nghĩa mô hình được nêu.","K-means không có biến đích liên tục cần dự đoán.","Association rules tìm đồng xuất hiện itemsets.","Regression trees cũng dự đoán số được; trong câu định nghĩa chương Regression, A là đáp án trực tiếp."],"caution":"Decision trees có cả regression trees. Không học rằng cây chỉ dự đoán được categorical; A là lựa chọn theo định nghĩa được trích.","topic":"Regression","gradable":true,"keyChanged":false,"bookPage":162,"pdfPage":182,"reference":"Sách chương 6, trang 162 (PDF trang 182) · Slide chương 6, slide 4","slideNumbers":[4],"keywords":["several input variables","continuous outcome"]},{"id":43,"stem":"What action might a data scientist need to take with variables to improve model adherence?","options":["Transforming the variables, as appropriate.","Deleting variables to simplify the model.","Duplicating variables to increase data volume.","Ignoring variable discrepancies."],"image":"assets/dta301/su26/43.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":6,"sourceTerm":"transform","detail":"Có thể biến đổi biến phù hợp để quan hệ, độ phân tán hoặc phần dư đáp ứng giả định mô hình tốt hơn.","trick":"Transform phải có lý do và kiểm tra lại model.","why":["Đúng hành động có điều kiện “as appropriate”.","Xóa biến không mặc nhiên cải thiện giả định và có thể mất tín hiệu.","Nhân bản biến làm tăng trùng lặp, không sửa vi phạm giả định.","Bỏ qua discrepancy không giải quyết vấn đề."],"caution":"","topic":"Regression","gradable":true,"keyChanged":false,"bookPage":162,"pdfPage":182,"reference":"Sách chương 6, trang 162 (PDF trang 182) · Slide chương 6, slide 54, 58","slideNumbers":[54,58],"keywords":["variables","improve model adherence"]},{"id":44,"stem":"MapReduce paradigm provides the means to break a large task into smaller tasks, run the tasks in sequence, and consolidate the outputs of the individual tasks into the final output?","options":["True","False"],"image":"assets/dta301/su26/44.jpg","suppliedKey":"B","multiple":false,"correct":[1],"chapter":10,"sourceTerm":"parallel","detail":"MapReduce chia công việc thành nhiều task để thực hiện song song; câu nói “in sequence” sai.","trick":"Bẫy sequence → phải là parallel.","why":["Sai vì thay song song bằng tuần tự.","Đúng: phát biểu bị sai ở cách thực thi các task."],"caution":"Trong một job, các giai đoạn vẫn có phụ thuộc; ý sai là nói các task được chạy tuần tự thay vì tận dụng song song.","topic":"MapReduce và Hadoop","gradable":true,"keyChanged":false,"bookPage":292,"pdfPage":312,"reference":"Sách chương 10, trang 292 (PDF trang 312) · Slide chương 10, slide 5, 6, 10","slideNumbers":[5,6,10],"keywords":["MapReduce","run the tasks in sequence"]},{"id":45,"stem":"Who has less technical depth but has a basic knowledge of statistics or machine learning and can define key questions that can be answered using advanced analytics?","options":["Data Savvy Professionals","Technology and Data Enablers","Deep Analytical Talent","Database Administrators"],"image":"assets/dta301/su26/45.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":1,"sourceTerm":"Data Savvy Professionals","detail":"Data Savvy Professionals đủ hiểu thống kê/ML để xác định câu hỏi nghiệp vụ, nhưng có độ sâu kỹ thuật thấp hơn nhóm phân tích chuyên sâu.","trick":"Savvy biết hỏi “doanh nghiệp cần gì?”.","why":["Khớp mô tả hiểu dữ liệu để đặt câu hỏi.","Cung cấp hạ tầng và công nghệ.","Có độ sâu kỹ thuật và phân tích cao.","DBA tập trung quản trị cơ sở dữ liệu, không phải nhóm vai trò được hỏi."],"caution":"","topic":"Big Data và vai trò","gradable":true,"keyChanged":false,"bookPage":20,"pdfPage":40,"reference":"Sách chương 1, trang 20 (PDF trang 40) · Slides chương 1","slideNumbers":[],"keywords":["less technical depth","define key questions"]},{"id":46,"stem":"The dataset has four columns, with Student ID first. Does this exclude Student ID from k-means input?\nkmdata_orig = as.matrix(grade_input[,c(\"Student\",\"English\",\"Math\",\"Science\")])\nkmdata <- kmdata_orig[,2:4]","options":["True","False"],"image":"assets/dta301/su26/46.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":4,"sourceTerm":"Student","detail":"Chỉ số [,2:4] giữ mọi dòng và ba cột 2 đến 4, nên loại Student ở cột 1.","trick":"Trước dấu phẩy = dòng; sau = cột.","why":["Đúng thao tác loại cột ID khỏi đầu vào khoảng cách.","Sai vì cột 1 không nằm trong dải 2:4."],"caution":"Nếu Student là chuỗi, as.matrix trên cả data frame có thể ép mọi cột sang character. Sau khi bỏ ID vẫn cần bảo đảm kmdata là numeric trước kmeans. Câu chỉ hỏi việc loại cột ID.","topic":"Clustering","gradable":true,"keyChanged":false,"bookPage":116,"pdfPage":136,"reference":"Sách chương 4, trang 116 (PDF trang 136) · Slide chương 4, slide 2, 19, 22","slideNumbers":[2,19,22],"keywords":["Student ID","exclude","[,2:4]"]},{"id":47,"stem":"The following statement will return: SELECT '123a567' ~ '87*';","options":["True","False","Error","Empty"],"image":"assets/dta301/su26/47.jpg","suppliedKey":"B","multiple":false,"correct":[1],"chapter":11,"sourceTerm":"Regular Expressions","detail":"87* nghĩa là ký tự 8 theo sau bởi 0 hoặc nhiều ký tự 7. Dù * cho phép 0 lần của 7, ký tự 8 vẫn bắt buộc; chuỗi không có 8.","trick":"* chỉ tác động ký tự ngay trước nó: 87* vẫn cần 8.","why":["Sai vì không có ký tự 8 để bắt đầu match.","Đúng false vì thiếu 8.","Regex 87* và toán tử ~ hợp lệ.","~ trả boolean chứ không trả tập rỗng."],"caution":"","topic":"SQL và công cụ","gradable":true,"keyChanged":false,"bookPage":340,"pdfPage":360,"reference":"Sách chương 11, trang 340 (PDF trang 360) · Slide chương 11, slide 13","slideNumbers":[13],"keywords":["SELECT","'87*'"]},{"id":48,"stem":"The formula (xc,yc) = (Σxi/m, Σyi/m) is used to ____.","options":["Calculate the centroid (xc,yc) of the m points in a k-means cluster in two dimensions.","Compute the distance from each data point to each centroid and assign each point to the closest centroid."],"image":"assets/dta301/su26/48.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":4,"sourceTerm":"centroid","detail":"Tâm cụm là trung bình từng tọa độ của các điểm thuộc cụm.","trick":"Σ tọa độ / số điểm = tâm cụm.","why":["Đúng công thức lấy trung bình x và y.","Khoảng cách Euclid có căn và bình phương sai khác tọa độ."],"caution":"","topic":"Clustering","gradable":true,"keyChanged":false,"bookPage":121,"pdfPage":141,"reference":"Sách chương 4, trang 121 (PDF trang 141) · Slide chương 4, slide 14","slideNumbers":[14],"keywords":["(xc,yc)","(Σxi/m, Σyi/m)"]},{"id":49,"stem":"What decision does a data scientist need to make regarding model building?","options":["Deciding whether building one comprehensive model or many models on partitions of the data is best.","Always building the simplest possible model.","Building models only on randomly selected data subsets.","Building a model that ignores all data partitions."],"image":"assets/dta301/su26/49.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":6,"sourceTerm":"one comprehensive","detail":"Trong Model Building, team cân nhắc một mô hình chung hay nhiều mô hình cho các phân vùng dữ liệu tùy mục tiêu và khác biệt của các nhóm.","trick":"Một model hay nhiều model = quyết định cần đánh giá.","why":["Đúng quyết định một mô hình tổng thể hoặc nhiều mô hình theo partition.","Đơn giản là tiêu chí hữu ích nhưng “always” bỏ qua độ phù hợp và mục tiêu.","Không có quy tắc bắt buộc chỉ học trên tập ngẫu nhiên.","Bỏ qua partitions có thể che mất khác biệt quan trọng."],"caution":"","topic":"Regression","gradable":true,"keyChanged":false,"reference":"Sách chương 6, trang 190 (PDF trang 210) · Slide chương 6, slide 58","slideNumbers":[58],"bookPage":190,"pdfPage":210,"keywords":["decision","model building"]},{"id":50,"stem":"Which of the followings is correct statement used to add an additional column to dataset in R?","options":["sales%per_order <- sales$sales_total/sales$num_of_orders","sales+per_order <- sales$sales_total/sales$num_of_orders","addcol(per_order) < sales$sales_total/sales$num_of_orders","sales$per_order <- sales$sales_total/sales$num_of_orders"],"image":"assets/dta301/su26/50.jpg","suppliedKey":"D","multiple":false,"correct":[3],"chapter":3,"sourceTerm":"per_order","detail":"Dùng data_frame$tên_cột <- biểu_thức để thêm cột. Ở đây lấy tổng doanh thu chia số đơn.","trick":"Dấu $ chọn cột; <- gán dữ liệu.","why":["% không phải toán tử truy cập cột như $.","+ là phép cộng, không dùng để tạo cột theo cú pháp này.","addcol(per_order) không phải cú pháp thêm cột base R, và < không phải <-.","Cú pháp truy cập cột và phép gán đều đúng."],"caution":"","topic":"R và thống kê cơ bản","gradable":true,"keyChanged":false,"bookPage":70,"pdfPage":90,"reference":"Sách chương 3, trang 70 (PDF trang 90) · Slides chương 3","slideNumbers":[],"keywords":["add an additional column","R"]},{"id":51,"stem":"If the task is to identify the effect of drug A compared to drug B on patients, the null hypothesis and alternative hypothesis would be:","options":["HO: Drug A and drug B have the same effect on patients.","HO: Drug A has a greater effect than drug B on patients.","HA: Drug A and drug B have the same effect on patients."],"image":"assets/dta301/su26/51.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":3,"sourceTerm":"null hypothesis","detail":"Giả thuyết không H0 thường mô tả không có khác biệt hiệu quả giữa thuốc A và B. Nếu hỏi hai phía, HA là có khác biệt.","trick":"H0 = chưa khác; HA = có khác.","why":["Đúng phát biểu H0 về không khác biệt.","Greater effect là giả thuyết có hướng, không phải H0 bằng nhau trong câu này.","Gán hai thuốc bằng nhau cho HA là đảo vai trò H0/HA."],"caution":"Câu yêu cầu cả H0 và HA nhưng A chỉ cung cấp H0. Đây là phương án đúng nhất trong danh sách; cặp đầy đủ hai phía: H0: μA=μB; HA: μA≠μB.","topic":"R và thống kê cơ bản","gradable":true,"keyChanged":false,"bookPage":102,"pdfPage":122,"reference":"Sách chương 3, trang 102 (PDF trang 122) · Slide chương 3, slide 69, 70, 71","slideNumbers":[69,70,71],"keywords":["drug A compared to drug B","null hypothesis","alternative hypothesis"]},{"id":52,"stem":"The expected defaults for headers, column separators, and decimal point notations of read.delim() function are ____.","options":["header=FALSE, sep=\"\", dec=\".\"","header=TRUE, sep=\",\", dec=\".\"","header=TRUE, sep=\";\", dec=\",\"","header=TRUE, sep=\"\\t\", dec=\".\"","header=TRUE, sep=\"\\t\", dec=\",\""],"image":"assets/dta301/su26/52.jpg","suppliedKey":"D","multiple":false,"correct":[3],"chapter":3,"sourceTerm":"read.delim","detail":"read.delim mặc định header=TRUE, sep=\"\\t\", dec=\".\".","trick":"DELIM = TAB; bản thường dùng chấm.","why":["Đây là mặc định read.table.","Dấu phẩy là kiểu read.csv.","Dấu chấm phẩy và dấu phẩy thập phân là kiểu read.csv2.","Đúng cả header, tab và dấu chấm thập phân.","Đây là read.delim2 vì dùng dấu phẩy thập phân."],"caution":"","topic":"R và thống kê cơ bản","gradable":true,"keyChanged":false,"bookPage":69,"pdfPage":89,"reference":"Sách chương 3, trang 69 (PDF trang 89) · Slide chương 3, slide 15, 16","slideNumbers":[15,16],"keywords":["defaults","read.delim()"]},{"id":53,"stem":"Which of the followings is NOT a step in a text analysis process?","options":["Parsing","Search and retrieval","Text mining","Discover meaningful insights"],"image":"assets/dta301/su26/53.jpg","suppliedKey":"C","multiple":false,"correct":[3],"chapter":9,"sourceTerm":"Text Analysis Steps","detail":"Theo khung ba bước của sách: Parsing → Search and retrieval → Text mining. “Discover meaningful insights” là mục tiêu/kết quả của Text mining, không phải tên bước thứ tư độc lập trong khung này.","trick":"Ba tên bước: Parse – Search – Mine.","why":["Là bước 1 của khung ba bước.","Là bước 2.","Là bước 3, nên key C trong ảnh sai.","Không là bước độc lập trong danh sách ba bước đang được hỏi."],"caution":"Key ảnh chọn C; sửa D theo mục 9.1 và slide 6. Theo quy trình sáu phần ở cuối chương, gaining insights vẫn là một hoạt động; đáp án D phụ thuộc khung ba bước của câu trích.","topic":"Text Analysis","gradable":true,"keyChanged":true,"bookPage":257,"pdfPage":277,"reference":"Sách chương 9, trang 257 (PDF trang 277) · Slide chương 9, slide 3, 6","slideNumbers":[3,6],"keywords":["NOT","text analysis process"]},{"id":54,"stem":"Who are someone who understands the domain area and usually benefits from the results?","options":["Business user","Project sponsor","Business intelligence analyst","Project Manager"],"image":"assets/dta301/su26/54.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":2,"sourceTerm":"Business User","detail":"Business User hiểu lĩnh vực nghiệp vụ và thường hưởng lợi trực tiếp từ kết quả phân tích.","trick":"User hiểu việc và dùng kết quả.","why":["Đúng vai trò domain user.","Sponsor bảo trợ/tài trợ và quan tâm business impact/ROI.","BI Analyst tập trung báo cáo và dashboard.","Project Manager điều phối tiến độ, phạm vi, ngân sách."],"caution":"","topic":"Data Analytics Lifecycle","gradable":true,"keyChanged":false,"bookPage":27,"pdfPage":47,"reference":"Sách chương 2, trang 27 (PDF trang 47) · Slide chương 2, slide 4, 31","slideNumbers":[4,31],"keywords":["understands the domain area","benefits from the results"]},{"id":55,"stem":"Who typically need to share the code from the analytical project and create technical documents that describe how to implement the code at the conclusion of a project?","options":["Data Engineer and Database Administrator (DBA)","Business Intelligence Analyst","Project Manager","Business User"],"image":"assets/dta301/su26/55.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":12,"sourceTerm":"technical documents","detail":"Data Engineer và DBA cần chia sẻ code cùng tài liệu kỹ thuật mô tả cách triển khai.","trick":"Engineer/DBA = code chạy được + hướng dẫn triển khai.","why":["Đúng vai trò trong mục key outputs.","BI Analyst quan tâm báo cáo/dashboard.","Project Manager đánh giá tiến độ/ngân sách.","Business User quan tâm lợi ích nghiệp vụ."],"caution":"","topic":"Báo cáo và triển khai","gradable":true,"keyChanged":false,"bookPage":362,"pdfPage":382,"reference":"Sách chương 12, trang 362 (PDF trang 382) · Slides chương 12","slideNumbers":[],"keywords":["share the code","technical documents"]},{"id":56,"stem":"What is the primary purpose of ARIMA models?","options":["To perform time series analysis on dependent observations.","To analyze independent observations.","To categorize data into distinct clusters.","To generate random data for simulations."],"image":"assets/dta301/su26/56.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":8,"sourceTerm":"ARIMA","detail":"ARIMA dùng cho mô hình hóa/phân tích và dự báo chuỗi thời gian có cấu trúc phụ thuộc trễ.","trick":"ARIMA = chuỗi theo thời gian, có nhớ quá khứ.","why":["Đúng lựa chọn phù hợp mô tả trong chương.","Không phải đặc trưng mục đích của ARIMA trong đoạn này.","Phân cụm dùng clustering.","Mô phỏng ngẫu nhiên có thể dùng mô hình đã fit nhưng không phải mục đích chính được hỏi."],"caution":"","topic":"Time Series","gradable":true,"keyChanged":false,"bookPage":236,"pdfPage":256,"reference":"Sách chương 8, trang 236 (PDF trang 256) · Slide chương 8, slide 2, 3, 7","slideNumbers":[2,3,7],"keywords":["primary purpose","ARIMA"]},{"id":57,"stem":"\"Organizations evolve their processes and see the opportunities from Big Data. Move beyond traditional BI activities, such as using data to populate reports and dashboards, and move toward Data Science-driven projects that attempt to answer more open-ended and complex questions.” According to the provided text, what is a key shift organizations make in their data utilization?","options":["Transitioning from traditional Business Intelligence to Data Science-driven projects for complex inquiries.","Returning to manual, paper-based data collection methods.","Focusing solely on generating simple, static reports and dashboards.","Decreasing their reliance on data for decision-making processes."],"image":"assets/dta301/su26/57.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":1,"sourceTerm":"open-ended","detail":"Đoạn trích nói về mở rộng từ BI báo cáo/dashboard sang Data Science giải các câu hỏi mở và phức tạp.","trick":"BI mô tả đã xảy ra; DS mở rộng điều tra và mô hình.","why":["Đúng thay đổi được mô tả.","Không có ý quay lại thu thập giấy thủ công.","Trái với “move beyond traditional BI”.","Trái với tận dụng cơ hội từ Big Data."],"caution":"BI vẫn có giá trị và tiếp tục tồn tại; đoạn nói mở rộng năng lực, không yêu cầu loại bỏ dashboard.","topic":"Big Data và vai trò","gradable":true,"keyChanged":false,"bookPage":12,"pdfPage":32,"reference":"Sách chương 1, trang 12 (PDF trang 32) · Slide chương 1, slide 14, 22","slideNumbers":[14,22],"keywords":["traditional BI","open-ended and complex questions","key shift"]},{"id":58,"stem":"What measures the difference in the probability of X and Y appearing together in the dataset compared to what would be expected if X and Y were statistically independent of each other? A Lift","options":["Lift","Leverage","Confidence","Support"],"image":"assets/dta301/su26/58.jpg","suppliedKey":"B","multiple":false,"correct":[1],"chapter":5,"sourceTerm":"leverage","detail":"Leverage = P(X∩Y) − P(X)P(Y), đo chênh lệch xác suất so với độc lập.","trick":"Leverage = trừ / “difference”.","why":["Lift là tỷ số.","Leverage đúng công thức hiệu xác suất.","Confidence là xác suất điều kiện.","Support là xác suất đồng xuất hiện thực tế."],"caution":"","topic":"Association Rules","gradable":true,"keyChanged":false,"bookPage":142,"pdfPage":162,"reference":"Sách chương 5, trang 142 (PDF trang 162) · Slide chương 5, slide 16","slideNumbers":[16],"keywords":["difference in the probability","statistically independent"]},{"id":59,"stem":"Presentation for contains high-level takeaways for executive-level stakeholders, with a few key messages to aid their decision-making process?","options":["Project Sponsors","Analysts","Technical people","Database administrators"],"image":"assets/dta301/su26/59.jpg","suppliedKey":"A","multiple":false,"correct":[0],"chapter":12,"sourceTerm":"executive","detail":"Presentation for Project Sponsors ưu tiên thông điệp cấp cao, giá trị kinh doanh và hỗ trợ quyết định.","trick":"Sponsor cần quyết định; Analyst cần chi tiết.","why":["Đúng đối tượng executive-level.","Analyst cần chi tiết phương pháp, biến và kiểm định mô hình.","Technical people cần code và tài liệu triển khai.","DBA cần nội dung vận hành/dữ liệu, không phải bài trình bày executive."],"caution":"","topic":"Báo cáo và triển khai","gradable":true,"keyChanged":false,"bookPage":362,"pdfPage":382,"reference":"Sách chương 12, trang 362 (PDF trang 382) · Slide chương 12, slide 14, 16, 17","slideNumbers":[14,16,17],"keywords":["high-level takeaways","executive-level stakeholders"]},{"id":60,"stem":"Which of the followings uses the terms and indexes produced by the prior two steps to discover meaningful insights pertaining to domains or problems of interest?","options":["Parsing","Search and retrieval","Text mining","Discover meaningful insights"],"image":"assets/dta301/su26/60.jpg","suppliedKey":"D","multiple":false,"correct":[2],"chapter":9,"sourceTerm":"uses the terms","detail":"Text mining dùng terms và indexes đã được tạo bởi parsing và search/retrieval để khám phá insight.","trick":"Terms + indexes → Mine để tìm insights.","why":["Parsing tạo biểu diễn/cấu trúc đầu vào.","Search and retrieval dùng cấu trúc để tìm tài liệu liên quan.","Đúng tên bước dùng đầu ra của hai bước trước.","Chỉ lặp lại mục tiêu “discover meaningful insights”, không phải tên bước theo định nghĩa."],"caution":"Key ảnh chọn D; sửa C theo nguyên văn định nghĩa Text mining trong mục 9.1 và slide 6.","topic":"Text Analysis","gradable":true,"keyChanged":true,"bookPage":257,"pdfPage":277,"reference":"Sách chương 9, trang 257 (PDF trang 277) · Slide chương 9, slide 6","slideNumbers":[6],"keywords":["terms and indexes","discover meaningful insights"]}],"subject":"dta301","legacyExamId":"su26"}});